function triageScore(patient) {
  const { vitals, symptoms } = patient;
  let score = 0;

  if (vitals.spo2 < 90) score += 40;
  if (vitals.heartRate > 130) score += 25;
  if (symptoms.includes("chest_pain")) score += 30;

  return score >= 60 ? "CRITICAL" : "STABLE";
}

app.post("/dispatch", async (req, res) => {
  const level = triageScore(req.body);
  await queue.push({ level, patient: req.body });
  res.json({ level });
});

def check_price(url):
    res = requests.get(url, headers=HEADERS)
    soup = BeautifulSoup(res.text, "html.parser")
    price = soup.select_one(".price").get_text(strip=True)

    if float(price[1:]) < TARGET_PRICE:
        send_telegram_alert(
            "Price drop! Now " + price
        )

    return price
